    "passage": "“What stories like this do for us is make the world just a smidge bigger, ” writes Stephen Graham Jones in the foreword to Never Whistle at Night: An Indigenous Dark Fiction Anthology. For Jones, dark fiction does more than entertain readers: ______ horror tropes to challenge familiar ways of knowing, blurring the “borders of the real. ”",
