    "explanation": "Choice C is the best answer. The convention being tested is the use of verb forms within a sentence. Relative clauses, such as the one beginning with “that,” require a finite (tensed) verb, a verb that can function as the main verb of a clause. This choice correctly supplies the clause with the finite present tense verb “results.” Furthermore, the simple present tense verb “results” correctly indicates that the formation of parallel arrays of long polygonal prisms is an enduring property of this fracturing pattern.\n Choice A is incorrect because it results in an ungrammatical sentence. The nonfinite participle “resulting” doesn’t supply the clause with a finite verb.\n Choice B is incorrect because the past progressive tense verb “were resulting” doesn’t indicate that the formation of parallel arrays of long polygonal prisms is an enduring property of this fracturing pattern.\n Choice D is incorrect because it results in an ungrammatical sentence. The nonfinite to-infinitive “to result” doesn’t supply the clause with a finite verb."
