    "explanation": "Choice B is the best answer. The convention being tested is the use of verbs to express tense. In this choice, the present tense verb \"illuminates\"is consistent with the other present tense verb (\"is\") used to describe the sculpture, correctly indicating that the sculpture habitually glows (\"each night\") and that the lamp inside is the source of its illumination.\n Choice A is incorrect because the future progressive tense verb \"will be illuminating\"isn’t consistent with the other present tense verb used to describe the sculpture and the source of its glow.\n Choice C is incorrect because the modal \"would,\"which is used to indicate a typical behavior in the past, isn’t consistent with the other present tense verb used to describe the sculpture and the source of its glow.\n Choice D is incorrect because the past tense verb \"illuminated\"isn’t consistent with the other present tense verb used to describe the sculpture and the source of its glow."
