    "explanation": "Choice C is the best answer. The convention being tested is the use of nonfinite verb forms within a sentence. The nonfinite present participle \"including\"is correctly used to form a participial phrase that supplements the main clause \"he patented many inventions,\"listing several of Spikes’s patented inventions.\n Choice A is incorrect because the finite past tense verb \"included\"can’t be used in this way to supplement the main clause \"he patented many inventions.\"Choice B is incorrect because the finite present tense verb \"includes\"can’t be used in this way to supplement the main clause \"he patented many inventions.\"Choice D is incorrect because the finite future tense verb \"will include\"can’t be used in this way to supplement the main clause \"he patented many inventions.\""
