    "explanation": "Choice D is the best answer. The convention being tested is pronoun-antecedent agreement. The singular pronoun \"he\"agrees in number with the singular antecedent \"Félix González-Torres,\"and it clearly indicates that González-Torres created the additional installations.\n Choice A is incorrect because the plural noun phrase \"they all\"doesn’t agree in number with the singular antecedent \"Félix González-Torres,\"and it doesn’t clearly indicate that he (González-Torres) created the additional installations.\n Choice B is incorrect because the plural pronoun \"those\"doesn’t agree in number with the singular antecedent \"Félix González-Torres,\"and it doesn’t clearly indicate that he (González-Torres) created the additional installations.\n Choice C is incorrect because the plural pronoun \"both\"doesn’t agree in number with the singular antecedent \"Félix González-Torres,\"and it doesn’t clearly indicate that he (González-Torres) created the additional installations."
