    "subtopicId": "form-structure",
    "subtopic": "Form, structure, and sense",
    "difficulty": "medium",
    "passage": "Many folktales that originate in the Czech language start with a phrase that roughly translates to “there was, there was not. ” Many tales that originate in English use “once upon a time. ” Such phrases, known as story starters, ______ from language to language.",
    "stem": "Which choice completes the text so that it conforms to the conventions of Standard English?",
