    "correctAnswer": "C",
    "explanation": "Choice C is the best answer. The convention being tested is the use of possessive determiners. The singular possessive determiner \"its\"agrees in number with the singular subject \"the Tajik Republic\"and thus indicates that the other republics were its peers.\n Choice A is incorrect because the plural possessive determiner \"their\"doesn’t agree in number with the singular subject \"the Tajik Republic.\"Choice B is incorrect because \"they’re\"is the contraction for \"they are,\"not a possessive determiner.\n Choice D is incorrect because \"it’s\"is the contraction for \"it is\"or \"it has,\"not a possessive determiner."
