    "passage": "Several advantages—the ability to react strongly with chip components, to avoid interference from other waves, and to be confined within tiny circuits—______ acoustic waves as a promising alternative to electrical waves for transmitting data on computer chips; as a result, researchers are invested in developing more acoustic wave–based chips.",
